export const BENCH_SUITES={
 'native-extraction':{label:'Isolated extraction',method:'native-tool',checks:{isolation:'Isolation startup succeeds',payload:'Known payload and exclusions verified',integrity:'Original and output hashes verified',limits:'Malformed and oversized members rejected',cancellation:'Cancellation preserves status', 'host-inspection':'Network, mounts and limits independently inspected'}},
 'browser-release':{label:'Browser release',method:'browser',checks:{migration:'Legacy assessment migration',roundtrip:'Export/import bytes and links',offline:'Actual offline reload',report:'Native PDF and report inspection',layout:'Keyboard and responsive layouts'}},
 'native-network':{label:'Native network',method:'native-tool',checks:{open:'Known listener reported open',closed:'Stopped listener reported closed','version-probes':'Controlled service identified by probes',allowlist:'Out-of-scope destinations rejected',cancellation:'Cancellation preserves partial output',integrity:'Original sizes/hashes independently checked'}},
 'physical-debugger':{label:'Physical debugger',method:'physical',checks:{attach:'Attach effects match the reviewed profile',registers:'Known register values verified',memory:'Known memory independently compared',breakpoint:'Hardware breakpoint hit and removed',watchpoint:'Aligned hardware watchpoint verified',symbols:'Matching symbols and backtrace reviewed',unplug:'Unplug retains evidence and unknown target state',reconnect:'Deliberate reconnect without replay',roundtrip:'Memory/session export and reimport verified'}},
 'physical-serial':{label:'Physical serial',method:'physical',checks:{startup:'Full startup captured with conditions',binary:'Known RX/TX bytes independently compared',endings:'Line endings and split reads verified',sustained:'Sustained capture and limits reviewed',unplug:'Unplug/reconnect without replay',roundtrip:'Raw bytes and evidence survive export/import'}}
};
export function validateBench(r){if(r?.format!=='probe-bench-v1'||!Object.hasOwn(BENCH_SUITES,r.suite)||!['native-tool','physical','simulated','browser'].includes(r.method)||!Array.isArray(r.checks)||r.checks.length>100||!r.environment||typeof r.environment!=='object'||Array.isArray(r.environment)||(r.evidence!==undefined&&!Array.isArray(r.evidence)))throw Error('Invalid bench record.');const seen=new Set();for(const c of r.checks){if(!c||typeof c.id!=='string'||seen.has(c.id)||!['passed','failed','blocked','not-run','inconclusive'].includes(c.status)||typeof c.detail!=='string'||c.detail.length>4000)throw Error('Invalid or duplicate bench check.');seen.add(c.id);}return r;}
export function benchOutcome(r){validateBench(r);const suite=BENCH_SUITES[r.suite],byId=new Map(r.checks.map(c=>[c.id,c]));if(r.checks.some(c=>c.status==='failed'))return 'Failed';if(r.method==='simulated')return 'Simulation only';if(Object.keys(suite.checks).some(id=>byId.get(id)?.status!=='passed'))return 'Pending';if(r.method!==suite.method)return 'Method mismatch';if(!r.environment.os||suite.method==='physical'&&(!r.operator||!r.environment.hardware||!r.environment.tools||!r.environment.conditions||!r.evidence?.length))return 'Context incomplete';return suite.method==='physical'?'Operator-recorded pass':'Tool-recorded pass';}
